 function road(g,x,y){const city=getCity(),kind=at(city,x,y)?.roadKind;if(kind==='bridge'){for(const a of [-3.8,3.8])box(g,a,-1.3,0,.45,3.1,6,'#a8a99b');box(g,0,-.1,0,10,.4,10,'#909a91')}box(g,0,.14,0,10,.28,10,'#a9aaa1',false);box(g,0,.3,0,7.1,.06,7.1,'#4d5555',false);let degree=0;for(const[a,b]of [[1,0],[-1,0],[0,1],[0,-1]])if(at(city,x+a,y+b)?.type==='road'){degree++;box(g,a*4,.3,b*4,a?3:7.1,.06,b?3:7.1,'#4d5555',false)}const ew=at(city,x+1,y)?.type==='road'||at(city,x-1,y)?.type==='road',ns=at(city,x,y+1)?.type==='road'||at(city,x,y-1)?.type==='road';if(degree>2){for(let k=-2;k<=2;k++){box(g,k*.83,.34,3.3,.43,.02,1.05,'#d3d1bc',false);box(g,3.3,.34,k*.83,1.05,.02,.43,'#d3d1bc',false)}box(g,4,1,4,.12,2,.12,'#59615b');box(g,4,2.1,4,.35,.65,.3,'#333f3c');box(g,4,2.2,4.17,.16,.16,.08,'#788b5a',false)}else if(ew&&!ns)for(const k of [-3,0,3])box(g,k,.34,0,1.7,.02,.1,'#cbbd89',false);else if(ns&&!ew)for(const k of [-3,0,3])box(g,0,.34,k,.1,.02,1.7,'#cbbd89',false);if(kind==='boulevard'){box(g,0,.4,0,1.3,.18,9.8,'#7b8d61',false);tree(g,0,0,.55,hash(x,y))}if(kind==='pedestrian'){box(g,0,.36,0,7,.07,7,'#afa68e',false);for(const a of [-2.5,2.5])box(g,a,.8,2.5,.6,.8,.6,'#768659')}if(kind==='oneway'){box(g,1,.36,0,1.8,.02,.2,'#c8c6ac',false);const arrow=box(g,1.7,.36,.35,.8,.02,.15,'#c8c6ac',false);arrow.rotation.y=-.7}lamp(g,4.25,-4.25);if(kind==='boulevard'||kind==='bridge')lamp(g,-4.25,4.25);if(hash(x,y,7)>.93){box(g,-4.1,.75,3.6,.55,1.3,.6,'#527465');box(g,-4.1,1.45,3.6,.65,.15,.7,'#475b50')}}
